<?php
require __DIR__.'/bootstrap.php';$slug=(string)($_GET['slug']??'');$q=$pdo->prepare('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.slug=? AND p.active=1');$q->execute([$slug]);$p=$q->fetch();if(!$p){http_response_code(404);site_header($pdo,'Product not found');echo '<div class="empty-state">Product not found. <a href="shop.php">Continue shopping</a></div>';site_footer($pdo);exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$qty=max(1,(int)($_POST['quantity']??1));if($qty>(int)$p['stock']){flash('Not enough stock available.','error');redirect('product.php?slug='.rawurlencode($slug));}$_SESSION['cart'][(int)$p['id']]=min((int)$p['stock'],(int)($_SESSION['cart'][(int)$p['id']]??0)+$qty);flash('Added to your bag.');redirect('cart.php');}
site_header($pdo,$p['name']);$rel=$pdo->prepare('SELECT * FROM products WHERE active=1 AND category_id=? AND id<>? LIMIT 4');$rel->execute([$p['category_id'],$p['id']]); ?>
<section class="section product-detail"><div><img class="detail-image" src="<?=e(product_image($p['image']))?>" alt="<?=e($p['name'])?>"></div><div class="detail-copy"><span class="eyebrow"><?=e($p['category_name']??'COLLECTION')?> · SKU <?=e($p['sku'])?></span><h1><?=e($p['name'])?></h1><div class="price"><?php if($p['sale_price'] && $p['sale_price']<$p['price']): ?><del><?=money((float)$p['price'])?></del><?php endif; ?> <?=money((float)($p['sale_price']?:$p['price']))?></div><p><?=nl2br(e($p['description']))?></p><p class="muted"><?=$p['stock']>0?'In stock — '.(int)$p['stock'].' available':'Currently unavailable'?></p><?php if($p['stock']>0): ?><form method="post" class="add-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Quantity <input type="number" name="quantity" value="1" min="1" max="<?= (int)$p['stock']?>"></label><button class="button" type="submit">ADD TO BAG</button></form><?php endif; ?><h3>Details</h3><p><?=nl2br(e($p['long_description']?:$p['description']))?></p></div></section><section class="section section-ivory"><div class="section-heading"><h2>You may also like</h2></div><div class="product-grid"><?php foreach($rel as $r): ?><article class="product-card"><a href="product.php?slug=<?=e($r['slug'])?>"><div class="product-image"><img src="<?=e(product_image($r['image']))?>" alt="<?=e($r['name'])?>" loading="lazy"></div><div class="product-meta"><h3><?=e($r['name'])?></h3><b><?=money((float)($r['sale_price']?:$r['price']))?></b></div></a></article><?php endforeach; ?></div></section><?php site_footer($pdo); ?>
